/**
 * Creates a chevron SVG icon element.
 * @returns {SVGElement}
 */
function ChevronIcon() {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 20 20');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '2');
  svg.setAttribute('stroke-linecap', 'round');
  svg.setAttribute('stroke-linejoin', 'round');
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('focusable', 'false');
  svg.classList.add('question__icon');

  const path = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
  path.setAttribute('points', '5 8 10 13 15 8');
  svg.appendChild(path);
  return svg;
}

/**
 * Renders a single FAQ disclosure item.
 * @param {{ id: string, question: string, answer: string }} props
 * @returns {HTMLLIElement}
 */
function FAQItem({ id, question, answer }) {
  const answerId = `${id}-answer`;

  // Wrapper: required .example class
  const wrapper = document.createElement('div');
  wrapper.classList.add('example');

  // Toggle button
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.classList.add('question');
  btn.setAttribute('aria-expanded', 'false');
  btn.setAttribute('aria-controls', answerId);
  btn.textContent = question;
  btn.appendChild(ChevronIcon());

  // Controlled content panel: required .details class
  const panel = document.createElement('div');
  panel.classList.add('details');
  panel.id = answerId;
  panel.setAttribute('aria-hidden', 'true');

  const inner = document.createElement('div');
  inner.classList.add('details__inner');

  // Render each paragraph separated by blank lines
  answer.trim().split(/\n\s*\n/).forEach((para) => {
    const p = document.createElement('p');
    p.textContent = para.trim();
    inner.appendChild(p);
  });

  panel.appendChild(inner);
  wrapper.appendChild(btn);
  wrapper.appendChild(panel);

  // Interaction
  btn.addEventListener('click', () => {
    const isExpanded = btn.getAttribute('aria-expanded') === 'true';
    btn.setAttribute('aria-expanded', String(!isExpanded));
    panel.setAttribute('aria-hidden', String(isExpanded));
  });

  // Keyboard: Escape collapses
  btn.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && btn.getAttribute('aria-expanded') === 'true') {
      btn.setAttribute('aria-expanded', 'false');
      panel.setAttribute('aria-hidden', 'true');
      btn.focus();
    }
  });

  return wrapper;
}

/**
 * Renders the full FAQ page into the given root element.
 * @param {HTMLElement} root
 * @param {{ title: string, subtitle: string, items: typeof FAQ_ITEMS }} props
 */
function FAQPage(root, { title, subtitle, items }) {
  const main = document.createElement('main');
  main.id = 'main-content';

  const wrapper = document.createElement('div');
  wrapper.classList.add('page-wrapper');

  // Header
  const header = document.createElement('header');
  header.classList.add('page-header');

  const eyebrow = document.createElement('span');
  eyebrow.classList.add('eyebrow');
  eyebrow.textContent = '🐱 Cat FAQ';

  const h1 = document.createElement('h1');
  h1.textContent = title;

  const subtitle_el = document.createElement('p');
  subtitle_el.textContent = subtitle;

  header.appendChild(eyebrow);
  header.appendChild(h1);
  header.appendChild(subtitle_el);

  // FAQ list
  const section = document.createElement('section');
  section.setAttribute('aria-label', 'Frequently asked questions about cats');

  const list = document.createElement('ul');
  list.classList.add('faq-list');
  list.setAttribute('role', 'list');

  items.forEach((item) => {
    const li = document.createElement('li');
    li.appendChild(FAQItem(item));
    list.appendChild(li);
  });

  section.appendChild(list);

  // Footer
  const footer = document.createElement('footer');
  footer.classList.add('page-footer');
  footer.setAttribute('role', 'contentinfo');
  footer.textContent = 'Select any question to expand the answer.';

  wrapper.appendChild(header);
  wrapper.appendChild(section);
  wrapper.appendChild(footer);
  main.appendChild(wrapper);
  root.appendChild(main);
}

// --- Bootstrap ---

document.addEventListener('DOMContentLoaded', () => {
  const root = document.getElementById('app');
  FAQPage(root, {
    title: 'Everything You Wanted to Know About Cats',
    subtitle: 'Answers to the most common questions about feline behavior, biology, and care.',
    items: FAQ_ITEMS,
  });
});
