+  max-width: 720px;
+  margin: 0 auto;
+}
+
+/* Header */
+.page-header {
+  text-align: center;
+  margin-bottom: 3rem;
+}
+
+.page-header .eyebrow {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.4rem;
+  font-size: 0.8125rem;
+  font-weight: 600;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  background: var(--color-accent-light);
+  padding: 0.3rem 0.75rem;
+  border-radius: 100px;
+  margin-bottom: 1rem;
+}
+
+.page-header h1 {
+  font-size: clamp(1.875rem, 5vw, 2.75rem);
+  font-weight: 700;
+  letter-spacing: -0.02em;
+  line-height: 1.15;
+  color: var(--color-text-primary);
+  margin-bottom: 0.75rem;
+}
+
+.page-header p {
+  font-size: 1.0625rem;
+  color: var(--color-text-secondary);
+  max-width: 480px;
+  margin: 0 auto;
+}
+
+/* FAQ list */
+.faq-list {
+  display: flex;
+  flex-direction: column;
+  gap: 0.75rem;
+  list-style: none;
+}
+
+/* Example wrapper (required class) */
+.example {
+  background: var(--color-surface);
+  border: 1.5px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow-sm);
+  overflow: hidden;
+  transition: border-color var(--transition), box-shadow var(--transition);
+}
+
+.example:has(.question[aria-expanded="true"]) {
+  border-color: var(--color-accent);
+  box-shadow: var(--shadow-md);
+}
+
+/* Question button */
+.question {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 1rem;
+  width: 100%;
+  padding: 1.25rem 1.5rem;
+  background: transparent;
+  border: none;
+  cursor: pointer;
+  text-align: left;
+  font-family: inherit;
+  font-size: 1rem;
+  font-weight: 600;
+  color: var(--color-text-primary);
+  line-height: 1.4;
+  transition: background var(--transition), color var(--transition);
+  border-radius: var(--radius-lg);
+}
+
+.question:hover {
+  background: var(--color-bg);
+}
+
+.question[aria-expanded="true"] {
+  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
+  color: var(--color-accent);
+  background: var(--color-accent-light);
+}
+
+.question:focus-visible {
+  outline: 3px solid var(--color-focus-ring);
+  outline-offset: -3px;
+}
+
+/* Chevron icon */
+.question__icon {
+  flex-shrink: 0;
+  width: 20px;
+  height: 20px;
+  color: var(--color-text-secondary);
+  transition: transform var(--transition), color var(--transition);
+  transform: rotate(0deg);
+}
+
+.question[aria-expanded="true"] .question__icon {
+  transform: rotate(180deg);
+  color: var(--color-accent);
+}
+
+/* Details panel (required class) */
+.details {
+  overflow: hidden;
+  max-height: 0;
+  transition: max-height 300ms cubic-bezier(0.4, 0, 0.2, 1);
+}
+
+.details[aria-hidden="false"] {
+  max-height: 600px;
+}
+
+.details__inner {
+  padding: 0 1.5rem 1.5rem;
+  border-top: 1.5px solid var(--color-border);
+}
+
+.details__inner p {
+  font-size: 0.9375rem;
+  color: var(--color-text-secondary);
+  line-height: 1.75;
+  margin-top: 1rem;
+}
+
+.details__inner p + p {
+  margin-top: 0.75rem;
+}
+
+/* Footer */
+.page-footer {
+  text-align: center;
+  margin-top: 3.5rem;
+  font-size: 0.8125rem;
+  color: var(--color-text-secondary);
+}
+
+/* Forced colors */
+@media (forced-colors: active) {
+  .question {
+    border: 2px solid ButtonBorder;
+    color: ButtonText;
+    background: ButtonFace;
+  }
+
+  .question[aria-expanded="true"] {
+    background: Highlight;
+    color: HighlightText;
+  }
+
+  .question__icon {
+    fill: currentColor;
+    stroke: currentColor;
+  }
+
+  .example {
+    border: 2px solid CanvasText;
+  }
+}
+
+/* Reflow at 320px */
+@media (max-width: 360px) {
+  .question {
+    padding: 1rem 1rem;
+    font-size: 0.9375rem;
+  }
+
+  .details__inner {
+    padding: 0 1rem 1rem;
+  }
+}
+
+/* Reduced motion */
+@media (prefers-reduced-motion: reduce) {
+  .question__icon,
+  .details,
+  .example {
+    transition: none;
+  }
+
+  .details[aria-hidden="false"] {
+    max-height: none;
+  }
+}
+
')

