+'use strict';
+
+// --- Data ---
+
+const FAQ_ITEMS = [
+  {
+    id: 'faq-lifespan',
+    question: 'How long do cats typically live?',
+    answer: `Indoor cats live an average of 12–18 years, though many reach their early 20s with good care. The oldest recorded cat, Creme Puff of Austin, Texas, lived to 38 years old.
+    
+    Key longevity factors include a balanced diet, regular veterinary checkups, keeping them indoors, and spaying or neutering.`,
+  },
+  {
+    id: 'faq-purring',
+    question: 'Why do cats purr?',
+    answer: `Purring is produced by rapid, rhythmic movement of the laryngeal muscles causing the glottis to dilate and constrict during inhalation and exhalation. It occurs at frequencies between 25–150 Hz — a range associated with promoting bone density and healing.
+    
+    Cats purr when content, but also when stressed, injured, or giving birth, so it functions as both a communication signal and a self-soothing mechanism.`,
+  },
+  {
+    id: 'faq-landing',
+    question: 'Do cats always land on their feet?',
+    answer: `Cats have a "righting reflex" — they use their flexible spine and lack of a collarbone to rotate their body mid-air so their feet face down. This reflex develops by 6–7 weeks of age.
+    
+    That said, falls from very low heights (under 1–2 feet) don't give them enough time to right themselves, and very high falls can still cause serious injuries.`,
+  },
+  {
+    id: 'faq-kneading',
+    question: 'Why do cats knead?',
+    answer: `Kneading — the rhythmic pushing of paws in and out against a soft surface — originates in kittenhood, when kittens knead their mother's belly to stimulate milk flow. Adult cats retain the behavior as a comfort response.
+    
+    Cats also knead to mark territory using scent glands in their paw pads, and females may knead to signal to males that they are receptive to mating.`,
+  },
+  {
+    id: 'faq-sleep',
+    question: 'How many hours a day do cats sleep?',
+    answer: `Cats sleep between 12 and 16 hours per day on average — and some sleep up to 20 hours. They are crepuscular hunters, naturally most active at dawn and dusk, so long rest periods conserve energy between bursts of activity.
+    
+    Kittens and senior cats tend to sleep even more. Much of cat sleep is light dozing that allows them to wake quickly — only about 25% is deep REM sleep.`,
+  },
+  {
+    id: 'faq-gifts',
+    question: 'Why do cats bring home dead animals?',
+    answer: `Cats are obligate carnivores and instinctive hunters even when well-fed. Bringing prey home is thought to be a learned mothering behavior — wild mother cats bring dead prey to teach kittens how to eat and hunt.
+    
+    Your cat may view you as part of its social group and is essentially "teaching" you. It's a token of trust, not a taunt.`,
+  },
+  {
+    id: 'faq-solitary',
+    question: 'Are cats naturally solitary animals?',
+    answer: `The domestic cat's wild ancestor, Felis lybica, is largely solitary — unlike wolves. However, domestic cats have adapted to social living over thousands of years of cohabitation with humans.
+    
+    Whether a cat is social depends heavily on early socialization (before 7 weeks of age). Feral colonies demonstrate that cats can form stable social groups when resources are abundant, suggesting their social nature is more flexible than once assumed.`,
+  },
+  {
+    id: 'faq-pupils',
+    question: 'Why do cats have vertical slit pupils?',
+    answer: `Vertical slit pupils allow a far greater range of pupil dilation than round pupils — roughly 135x the area change vs. ~15x in humans. This gives cats exceptional control over incoming light, enabling them to see in both bright sunlight and near-total darkness.
+    
+    Research from UC Berkeley found that slit pupils are most common in predators that ambush prey close to the ground. The vertical orientation also aids depth perception and estimating the distance to prey.`,
+  },
+];
+
+// --- Component functions ---
+
+/**
+ * Creates a chevron SVG icon element.
+ * @returns {SVGElement}
+ */
+function ChevronIcon() {
+  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
+  svg.setAttribute('viewBox', '0 0 20 20');
+  svg.setAttribute('fill', 'none');
+  svg.setAttribute('stroke', 'currentColor');
+  svg.setAttribute('stroke-width', '2');
+  svg.setAttribute('stroke-linecap', 'round');
+  svg.setAttribute('stroke-linejoin', 'round');
+  svg.setAttribute('aria-hidden', 'true');
+  svg.setAttribute('focusable', 'false');
+  svg.classList.add('question__icon');
+
+  const path = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
+  path.setAttribute('points', '5 8 10 13 15 8');
+  svg.appendChild(path);
+  return svg;
+}
+
+/**
+ * Renders a single FAQ disclosure item.
+ * @param {{ id: string, question: string, answer: string }} props
+ * @returns {HTMLLIElement}
+ */
+function FAQItem({ id, question, answer }) {
+  const answerId = `${id}-answer`;
+
+  // Wrapper: required .example class
+  const wrapper = document.createElement('div');
+  wrapper.classList.add('example');
+
+  // Toggle button
+  const btn = document.createElement('button');
+  btn.type = 'button';
+  btn.classList.add('question');
+  btn.setAttribute('aria-expanded', 'false');
+  btn.setAttribute('aria-controls', answerId);
+  btn.textContent = question;
+  btn.appendChild(ChevronIcon());
+
+  // Controlled content panel: required .details class
+  const panel = document.createElement('div');
+  panel.classList.add('details');
+  panel.id = answerId;
+  panel.setAttribute('aria-hidden', 'true');
+
+  const inner = document.createElement('div');
+  inner.classList.add('details__inner');
+
+  // Render each paragraph separated by blank lines
+  answer.trim().split(/\n\s*\n/).forEach((para) => {
+    const p = document.createElement('p');
+    p.textContent = para.trim();
+    inner.appendChild(p);
+  });
+
+  panel.appendChild(inner);
+  wrapper.appendChild(btn);
+  wrapper.appendChild(panel);
+
+  // Interaction
+  btn.addEventListener('click', () => {
+    const isExpanded = btn.getAttribute('aria-expanded') === 'true';
+    btn.setAttribute('aria-expanded', String(!isExpanded));
+    panel.setAttribute('aria-hidden', String(isExpanded));
+  });
+
+  // Keyboard: Escape collapses
+  btn.addEventListener('keydown', (e) => {
+    if (e.key === 'Escape' && btn.getAttribute('aria-expanded') === 'true') {
+      btn.setAttribute('aria-expanded', 'false');
+      panel.setAttribute('aria-hidden', 'true');
+      btn.focus();
+    }
+  });
+
+  return wrapper;
+}
+
+/**
+ * Renders the full FAQ page into the given root element.
+ * @param {HTMLElement} root
+ * @param {{ title: string, subtitle: string, items: typeof FAQ_ITEMS }} props
+ */
+function FAQPage(root, { title, subtitle, items }) {
+  const main = document.createElement('main');
+  main.id = 'main-content';
+
+  const wrapper = document.createElement('div');
+  wrapper.classList.add('page-wrapper');
+
+  // Header
+  const header = document.createElement('header');
+  header.classList.add('page-header');
+
+  const eyebrow = document.createElement('span');
+  eyebrow.classList.add('eyebrow');
+  eyebrow.textContent = '🐱 Cat FAQ';
+
+  const h1 = document.createElement('h1');
+  h1.textContent = title;
+
+  const subtitle_el = document.createElement('p');
+  subtitle_el.textContent = subtitle;
+
+  header.appendChild(eyebrow);
+  header.appendChild(h1);
+  header.appendChild(subtitle_el);
+
+  // FAQ list
+  const section = document.createElement('section');
+  section.setAttribute('aria-label', 'Frequently asked questions about cats');
+
+  const list = document.createElement('ul');
+  list.classList.add('faq-list');
+  list.setAttribute('role', 'list');
+
+  items.forEach((item) => {
+    const li = document.createElement('li');
+    li.appendChild(FAQItem(item));
+    list.appendChild(li);
+  });
+
+  section.appendChild(list);
+
+  // Footer
+  const footer = document.createElement('footer');
+  footer.classList.add('page-footer');
+  footer.setAttribute('role', 'contentinfo');
+  footer.textContent = 'Select any question to expand the answer.';
+
+  wrapper.appendChild(header);
+  wrapper.appendChild(section);
+  wrapper.appendChild(footer);
+  main.appendChild(wrapper);
+  root.appendChild(main);
+}
+
+// --- Bootstrap ---
+
+document.addEventListener('DOMContentLoaded', () => {
+  const root = document.getElementById('app');
+  FAQPage(root, {
+    title: 'Everything You Wanted to Know About Cats',
+    subtitle: 'Answers to the most common questions about feline behavior, biology, and care.',
+    items: FAQ_ITEMS,
+  });
+});
+
')

